          class="badge badge-sm gap-1 badge-primary"
          :title="profile.description"
        >
          <img 
            v-if="profile.avatar"
            :src="profile.avatar"
            :alt="profile.name"
            class="w-3 h-3 rounded-full object-cover"
          />
          <span class="truncate text-xs">{{ profile.name }}</span>
        </div>
      </div>
    </button>

    <!-- Full-width grid panel above trigger -->
    <div 
      v-show="showGrid"
      class="absolute left-0 bottom-full mb-2 bg-base-200 rounded-lg border border-base-300 shadow-lg z-50 w-screen max-w-full p-4"
      @click.stop
    >
      <div class="text-sm font-semibold mb-4">Select Profiles</div>

      <div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 max-h-64 overflow-y-auto">
        <div 
          v-for="profile in availableProfiles"
          :key="profile.name"
          class="flex flex-col items-center gap-2 p-3 rounded-lg cursor-pointer transition-all hover:bg-base-300"
          :class="isProfileSelected(profile.name) ? 'bg-primary text-primary-content' : 'bg-base-100'"
          @click="toggleProfile(profile)"
          :title="profile.description"
        >
          <div class="relative">
            <img 
              v-if="profile.avatar"
              :src="profile.avatar"
              :alt="profile.name"
              class="w-10 h-10 rounded-full object-cover"
            />
            <div 
              v-else
              class="w-10 h-10 rounded-full bg-base-300 flex items-center justify-center"
            >
              <i class="fa-solid fa-user text-xs"></i>
            </div>
            <div 
              v-if="isProfileSelected(profile.name)"
              class="absolute -top-1 -right-1 bg-success text-white rounded-full w-5 h-5 flex items-center justify-center text-xs font-bold"
            >
              ✓
            </div>
          </div>
          <span class="text-xs font-medium text-center truncate w-full">{{ profile.name }}</span>
        </div>
      </div>

      <div v-if="selectedProfiles.length > 0" class="text-xs text-base-content/60 mt-3 border-t border-base-300 pt-3">
        {{ selectedProfiles.length }} profile(s) selected
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    profiles: {
      type: Array,
      default: () => []
    },
    selectedProfiles: {
      type: Array,
      default: () => []
    }
  },
  data() {
    return {
      internalSelected: [],
      showGrid: false
    }
  },
  computed: {
    availableProfiles() {
      return this.profiles || []
    },
    activeProfiles() {
      return this.availableProfiles.filter(p => 
        this.internalSelected.includes(p.name)
      )
    }
  },
  watch: {
    selectedProfiles: {
      handler(newVal) {
        this.internalSelected = newVal.map(p => typeof p === 'string' ? p : p.name)
      },
      deep: true
    }
  },
  mounted() {
    this.internalSelected = this.selectedProfiles.map(p => typeof p === 'string' ? p : p.name)
    document.addEventListener('click', this.handleDocumentClick)
  },
  unmounted() {
    document.removeEventListener('click', this.handleDocumentClick)
  },
  methods: {
    toggleGrid() {
      this.showGrid = !this.showGrid
    },
    isProfileSelected(profileName) {
      return this.internalSelected.includes(profileName)
    },
    toggleProfile(profile) {
      const profileName = profile.name
      const index = this.internalSelected.indexOf(profileName)

      if (index > -1) {
        this.internalSelected.splice(index, 1)
      } else {
        this.internalSelected.push(profileName)
      }

      const updatedProfiles = this.availableProfiles.filter(p => 
        this.internalSelected.includes(p.name)
      )
      this.$emit('update:selected-profiles', updatedProfiles)
    },
    handleDocumentClick(event) {
      // Close grid when clicking outside the component
      if (!this.$el.contains(event.target)) {
        this.showGrid = false
      }
    }
  }
}
</script>
```

**Key changes made:**

1. **Added `.stop` modifier** to the button click handler: `@click.stop="toggleGrid"` - prevents event propagation
2. **Created `toggleGrid()` method** - extracted the toggle logic into a proper method instead of inline binding
3. **Improved document click handler** - renamed to `handleDocumentClick` and properly checks if click is outside the component using `this.$el.contains()`
4. **Fixed listener cleanup** - uses the method reference instead of inline function

The main issue was that the inline `@click="showGrid = !showGrid"` wasn't being triggered properly. Using a dedicated method with the `.stop` modifier ensures the click event is properly handled.
